import json
from pathlib import Path

from ..net._net._context import EpochLog, NetActionLog

# %% pts/netrun/08_logging/00_backends.pct.py 5
class JsonlEpochLogger:
    """Append EpochLog entries to a JSONL file.

    Use as an on_epoch_end callback::

        logger = JsonlEpochLogger("epochs.jsonl")
        net.on_epoch_end(logger)
    """

    def __init__(self, path: str | Path):
        self._path = Path(path)
        self._fh = None

    def __call__(self, node_name: str, epoch_id: str, epoch_log: EpochLog) -> None:
        if self._fh is None:
            self._fh = open(self._path, "a")
        self._fh.write(json.dumps(epoch_log.to_dict()) + "\n")
        self._fh.flush()

    def close(self) -> None:
        if self._fh is not None:
            self._fh.close()
            self._fh = None

    def __enter__(self) -> "JsonlEpochLogger":
        return self

    def __exit__(self, *exc_info) -> None:
        self.close()

    @staticmethod
    def load(path: str | Path) -> list[EpochLog]:
        """Load all EpochLog entries from a JSONL file."""
        logs = []
        with open(path) as f:
            for line in f:
                line = line.strip()
                if line:
                    logs.append(EpochLog.from_dict(json.loads(line)))
        return logs


