# %% pts/netrun/08_logging/00_backends.pct.py 7
class SqliteLogger:
    """Write EpochLog and NetActionLog entries to a SQLite database.

    Creates two tables: ``epoch_logs`` and ``net_action_logs``.

    Usage::

        logger = SqliteLogger("run.db")
        net.on_epoch_end(logger.epoch_handler)
        net.on_net_actions(logger.net_action_handler)
    """

    def __init__(self, path: str | Path):
        import sqlite3
        self._path = Path(path)
        self._conn = sqlite3.connect(str(self._path))
        self._conn.execute("""
            CREATE TABLE IF NOT EXISTS epoch_logs (
                epoch_id TEXT PRIMARY KEY,
                node_name TEXT NOT NULL,
                timestamp TEXT NOT NULL,
                outcome TEXT NOT NULL,
                duration_ms REAL,
                data TEXT NOT NULL
            )
        """)
        self._conn.execute("""
            CREATE TABLE IF NOT EXISTS net_action_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp TEXT NOT NULL,
                action_kind TEXT NOT NULL,
                epoch_id TEXT,
                data TEXT NOT NULL
            )
        """)
        self._conn.commit()

    def epoch_handler(self, node_name: str, epoch_id: str, epoch_log: EpochLog) -> None:
        """on_epoch_end callback handler."""
        self._conn.execute(
            "INSERT OR REPLACE INTO epoch_logs (epoch_id, node_name, timestamp, outcome, duration_ms, data) VALUES (?, ?, ?, ?, ?, ?)",
            (
                epoch_log.epoch_id,
                epoch_log.node_name,
                epoch_log.timestamp.isoformat(),
                epoch_log.outcome,
                epoch_log.duration_ms,
                json.dumps(epoch_log.to_dict()),
            ),
        )
        self._conn.commit()

    def net_action_handler(self, actions: list[NetActionLog]) -> None:
        """on_net_actions callback handler."""
        for action in actions:
            self._conn.execute(
                "INSERT INTO net_action_logs (timestamp, action_kind, epoch_id, data) VALUES (?, ?, ?, ?)",
                (
                    action.timestamp.isoformat(),
                    action.action_kind,
                    action.epoch_id,
                    json.dumps(action.to_dict()),
                ),
            )
        self._conn.commit()

    def load_epoch_logs(self) -> list[EpochLog]:
        """Load all EpochLog entries from the database."""
        cursor = self._conn.execute("SELECT data FROM epoch_logs ORDER BY timestamp")
        return [EpochLog.from_dict(json.loads(row[0])) for row in cursor.fetchall()]

    def load_net_action_logs(self) -> list[NetActionLog]:
        """Load all NetActionLog entries from the database."""
        cursor = self._conn.execute("SELECT data FROM net_action_logs ORDER BY id")
        return [NetActionLog.from_dict(json.loads(row[0])) for row in cursor.fetchall()]

    def close(self) -> None:
        if self._conn is not None:
            self._conn.close()
            self._conn = None

    def __enter__(self) -> "SqliteLogger":
        return self

    def __exit__(self, *exc_info) -> None:
        self.close()
